-- Default Sustainable Products
MERGE INTO products (id, title, category, gender_type, sizes_json, color, style, price, fabric_type, eco_material_info, carbon_saved_kg, water_saved_liters, eco_score, rating, reviews_count, stock, image_url, description) KEY(id) VALUES 
(1, 'Aura Handwoven Khadi Kurta', 'Kurtas', 'Men', '["S", "M", "L", "XL"]', 'Natural Off-White', 'Ethnic', 2499.0, 'Organic Khadi', '100% Hand-spun Khadi cotton spun on traditional amber charkha. Zero electrical energy used in weaving, colored with raw herbal washes.', 6.8, 2800.0, 98, 4.9, 64, 25, 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=700&auto=format&fit=crop&q=80', 'Breathable, lightweight handwoven khadi kurta for warm climates. Crafted by master weaver collectives in rural India.'),
(2, 'Terra Hemp Relaxed Trousers', 'Trousers', 'Unisex', '["S", "M", "L", "XL"]', 'Earthy Ochre', 'Casual', 2899.0, 'Hemp Fiber', '55% Pure Hemp, 45% Organic Cotton. Hemp requires 75% less water than traditional fibers and revitalizes soil nitrogen.', 7.4, 3100.0, 96, 4.8, 52, 30, 'https://images.unsplash.com/photo-1552902865-b72c031ac5ea?w=700&auto=format&fit=crop&q=80', 'Relaxed-fit everyday trousers with deep pockets and an elasticated drawstring waistband. Hypoallergenic and antimicrobial.'),
(3, 'Vriksha Bamboo Linen Midi Dress', 'Dresses', 'Women', '["XS", "S", "M", "L"]', 'Sage Green', 'Minimalist', 3499.0, 'Bamboo Linen', '100% Closed-loop bamboo linen. Bamboo produces 35% more oxygen than trees and thrives without any synthetic pesticides.', 8.2, 3400.0, 97, 4.9, 88, 20, 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?w=700&auto=format&fit=crop&q=80', 'Effortlessly elegant midi dress featuring coconut shell buttons, breathable drape, and subtle side slits.'),
(4, 'Neelam Botanical Indigo Shirt', 'Shirts', 'Men', '["S", "M", "L", "XL"]', 'Deep Indigo', 'Casual', 2199.0, 'Organic Cotton', 'GOTS certified organic cotton dyed using naturally fermented Indigofera tinctoria leaves. 100% non-toxic effluent runoff.', 5.5, 2300.0, 94, 4.7, 41, 18, 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?w=700&auto=format&fit=crop&q=80', 'Casual tailored button-down shirt. The artisanal indigo vat dye softens gracefully with every wash.'),
(5, 'Ahimsa Peace Silk Saree & Wrap', 'Dresses', 'Women', '["Free Size"]', 'Muted Rose', 'Ethnic', 5499.0, 'Ahimsa (Peace) Silk', 'Non-violent wild Eri silk where silkworms complete metamorphosis before cocoons are gently harvested. Zero cruelty.', 9.5, 4200.0, 99, 5.0, 39, 12, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?w=700&auto=format&fit=crop&q=80', 'Heirloom ceremonial saree handcrafted in Assam. Naturally thermoregulating with a soft, matte sheen.'),
(6, 'Prakriti Hand-Block Printed Tunic', 'Kurtas', 'Women', '["S", "M", "L", "XL"]', 'Mustard Yellow', 'Bohemian', 1999.0, 'Organic Cotton', 'Pure organic cotton printed using centuries-old Bagru mud resist technique (Dabu) and natural pomegranate rind dyes.', 4.9, 1900.0, 93, 4.6, 73, 35, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?w=700&auto=format&fit=crop&q=80', 'Flattering everyday tunic with side slits and wooden button accents. Hypoallergenic and ultra-soft.'),
(7, 'Jal Ocean-Recycled Active Tee', 'Shirts', 'Unisex', '["S", "M", "L", "XL"]', 'Coastal Slate', 'Athleisure', 1799.0, 'Recycled Ocean Plastic', '100% Post-consumer ocean plastics and discarded fishing nets regenerated into ultra-fine high performance wicking yarn.', 8.9, 3900.0, 95, 4.8, 67, 40, 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=700&auto=format&fit=crop&q=80', 'Moisture-wicking athletic tee engineered for yoga, running, and all-day movement. Prevents microplastic shed in wash.'),
(8, 'Bhoomi Recycled Denim Over-Jacket', 'Jackets', 'Unisex', '["M", "L", "XL"]', 'Vintage Washed Blue', 'Casual', 3999.0, 'Post-Consumer Recycled Denim', 'Spun from upcycled post-consumer denim scraps. Saves 8,000 liters of water compared to standard virgin denim jackets.', 11.2, 5800.0, 97, 4.9, 29, 15, 'https://images.unsplash.com/photo-1544441893-675973e31985?w=700&auto=format&fit=crop&q=80', 'Durable unisex trucker jacket with copper-toned recycled zinc buttons and deep internal utility pockets.');
